	}
	if rec := postInterrupt(t, `{"horizon":10,"tasks":[],"interrupts":[],"extra":1}`, "application/json"); rec.Code != http.StatusBadRequest {
		t.Fatalf("unknown field: status = %d, want 400", rec.Code)
	}
}

func TestInterruptStateless(t *testing.T) {
	body := intReq(50,
