		intIntrJSON("I1", 0, 2, 1, 10))
	first := interruptOK(t, body)
	second := interruptOK(t, body)
	a, _ := json.Marshal(first)
	b, _ := json.Marshal(second)
	if string(a) != string(b) {
		t.Fatalf("repeated analysis differs:\n%s\n%s", a, b)
	}
}

